From 58758885a52a50b45f94338b99f438d60e117b5d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:44:47 +0100
Subject: [PATCH] screenbrightnesscontrol: restore brightness when leaving a
 dimmer profile

Switching to Low Battery reduced the brightness, but plugging AC back in
left it there unless AC had its own brightness set. Remember the earlier
brightness and restore it, unless the user changed it in the meantime.

BUG: 484663
---
 .../bundled/screenbrightnesscontrol.cpp       | 46 ++++++++++++++++++-
 .../actions/bundled/screenbrightnesscontrol.h | 12 +++++
 2 files changed, 56 insertions(+), 2 deletions(-)

diff --git a/daemon/actions/bundled/screenbrightnesscontrol.cpp b/daemon/actions/bundled/screenbrightnesscontrol.cpp
index 8363723f8..29a572224 100644
--- a/daemon/actions/bundled/screenbrightnesscontrol.cpp
+++ b/daemon/actions/bundled/screenbrightnesscontrol.cpp
@@ -29,6 +29,8 @@ ScreenBrightnessControl::ScreenBrightnessControl(QObject *parent)
     : Action(parent)
 {
     connect(core()->screenBrightnessController(), &ScreenBrightnessController::displayAdded, this, &ScreenBrightnessControl::displayAdded);
+    connect(core()->screenBrightnessController(), &ScreenBrightnessController::brightnessChanged, this, &ScreenBrightnessControl::brightnessChanged);
+    connect(core(), &Core::profileChanged, this, &ScreenBrightnessControl::profileChanged);

     const auto devices = Solid::Device::listFromType(Solid::DeviceInterface::Battery, QString());
     for (const Solid::Device &device : devices) {
@@ -49,10 +51,42 @@ void ScreenBrightnessControl::displayAdded(const QString &displayId)
     }
 }

+void ScreenBrightnessControl::brightnessChanged(const QString &displayId,
+                                                const PowerDevil::BrightnessLogic::BrightnessInfo &,
+                                                const QString &,
+                                                const QString &sourceClientContext)
+{
+    // the user (or something else) picked a new brightness, don't override it later on
+    if (sourceClientContext != "profile_brightness"_L1) {
+        m_brightnessToRestore.remove(displayId);
+    }
+}
+
+void ScreenBrightnessControl::profileChanged(const QString &newProfile)
+{
+    if (m_brightnessToRestore.isEmpty() || profileRank(newProfile) > profileRank(m_profileToRestore)) {
+        return;
+    }
+    // back on the profile that was active before we reduced brightness, or an even less conservative one
+    if (!m_configuredBrightnessRatio.has_value()) {
+        ScreenBrightnessController *controller = core()->screenBrightnessController();
+        for (const auto &[displayId, brightness] : m_brightnessToRestore.asKeyValueRange()) {
+            if (controller->displayIds().contains(displayId)) {
+                controller->setBrightness(displayId, brightness, u"(internal)"_s, u"profile_brightness"_s, ScreenBrightnessController::SuppressIndicator);
+            }
+        }
+    }
+    m_brightnessToRestore.clear();
+}
+
+int ScreenBrightnessControl::profileRank(const QString &profile)
+{
+    return profile == "LowBattery"_L1 ? 2 : profile == "Battery"_L1 ? 1 : 0;
+}
+
 void ScreenBrightnessControl::onProfileLoad(const QString &previousProfile, const QString &newProfile)
 {
-    const bool isNewProfileMoreConservative = (newProfile == "Battery"_L1 && previousProfile == "AC"_L1)
-        || (newProfile == "LowBattery"_L1 && (previousProfile == "AC"_L1 || previousProfile == "Battery"_L1));
+    const bool isNewProfileMoreConservative = !previousProfile.isEmpty() && profileRank(newProfile) > profileRank(previousProfile);

     ScreenBrightnessController *controller = core()->screenBrightnessController();

@@ -68,6 +102,14 @@ void ScreenBrightnessControl::onProfileLoad(const QString &previousProfile, cons
         if (isNewProfileMoreConservative && controller->brightness(displayId) < newBrightness) {
             qCDebug(POWERDEVIL) << "Display" << displayId << "not changing brightness: current brightness is lower and the new profile is more conservative";
         } else {
+            // remember the brightness from before the first reduction, to restore it when leaving
+            // the more conservative profile(s) for one without a brightness setting of its own
+            if (isNewProfileMoreConservative && controller->brightness(displayId) > newBrightness && !m_brightnessToRestore.contains(displayId)) {
+                if (m_brightnessToRestore.isEmpty()) {
+                    m_profileToRestore = previousProfile;
+                }
+                m_brightnessToRestore.insert(displayId, controller->brightness(displayId));
+            }
             controller->setBrightness(displayId, newBrightness, u"(internal)"_s, u"profile_brightness"_s, ScreenBrightnessController::SuppressIndicator);
         }
     }
diff --git a/daemon/actions/bundled/screenbrightnesscontrol.h b/daemon/actions/bundled/screenbrightnesscontrol.h
index 3869e89f8..ff04ba92c 100644
--- a/daemon/actions/bundled/screenbrightnesscontrol.h
+++ b/daemon/actions/bundled/screenbrightnesscontrol.h
@@ -8,6 +8,9 @@
 #pragma once

 #include <powerdevilaction.h>
+#include <powerdevilbrightnesslogic.h>
+
+#include <QHash>

 namespace PowerDevil::BundledActions
 {
@@ -28,8 +31,17 @@ protected:

 private Q_SLOTS:
     void displayAdded(const QString &displayId);
+    void brightnessChanged(const QString &displayId,
+                           const PowerDevil::BrightnessLogic::BrightnessInfo &,
+                           const QString &sourceClientName,
+                           const QString &sourceClientContext);
+    void profileChanged(const QString &newProfile);

 private:
+    static int profileRank(const QString &profile);
+
+    QHash<QString, int> m_brightnessToRestore;
+    QString m_profileToRestore;
     std::optional<double> m_configuredBrightnessRatio;
     bool m_supportsBatteryProfiles = false;
 };
